cat > resources/book.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  // Unpublished books are only visible to the PATCH lookup.
  return ctx.sql`SELECT b.id, b.title, b.price_cents AS "priceCents", b.published_at AS "publishedAt", b.stock,
      a.id AS author_id, a.name AS author_name
    FROM book b LEFT JOIN author a ON a.id = b.author_id
    WHERE b.published OR ${ctx.phase === "lookup"}`;
}
EOF
cat > resources/book.command.ts <<'EOF'
export function update(input, ctx) {
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("priceCents" in input) ctx.db.exec(ctx.sql`UPDATE book SET price_cents = ${input.priceCents} WHERE id = ${ctx.id}`);
  if ("stock" in input) ctx.db.exec(ctx.sql`UPDATE book SET stock = ${input.stock} WHERE id = ${ctx.id}`);
}
EOF
cat > resources/search.handler.ts <<'EOF'
export default function search(value: string, ctx) {
  return ctx.sql`(strpos(lower(${ctx.property("title")}), lower(${value})) > 0 OR strpos(lower(${ctx.property("author.name")}), lower(${value})) > 0)`;
}
EOF
cat > resources/in_stock.handler.ts <<'EOF'
export default function inStock(value: string, ctx) {
  const stock = ctx.property("stock");
  return value === "true" ? ctx.sql`${stock} > 0` : ctx.sql`${stock} = 0`;
}
EOF
