cat > purchase.command.ts <<'EOF'
export function create(input, ctx) {
  const customer = ctx.get("customer");
  const prices = {};
  const stocks = {};
  const wanted = {};
  for (let i = 0; i < input.lines.length; i++) {
    const line = input.lines[i];
    const [book] = ctx.db.query(ctx.sql`SELECT price_cents, stock FROM book WHERE id = ${line.bookId} AND published FOR UPDATE`);
    if (!book) {
      ctx.reject({ message: `book ${line.bookId} is not available`, pointer: `/lines/${i}/bookId`, code: "book_unavailable", status: 422 });
    }
    prices[line.bookId] = book.price_cents;
    stocks[line.bookId] = book.stock;
    wanted[line.bookId] = (wanted[line.bookId] || 0) + line.quantity;
  }
  for (const key of Object.keys(wanted)) {
    if (wanted[key] > stocks[key]) {
      ctx.reject({ message: `not enough stock for book ${key}`, pointer: "/lines", code: "out_of_stock", status: 409 });
    }
  }
  let total = 0;
  for (const line of input.lines) {
    total += line.quantity * prices[line.bookId];
  }
  const [purchase] = ctx.db.query(ctx.sql`INSERT INTO purchase (customer_id, total_cents) VALUES (${customer}, ${total}) RETURNING id`);
  for (const line of input.lines) {
    ctx.db.exec(ctx.sql`INSERT INTO purchase_line (purchase_id, book_id, quantity, unit_price_cents) VALUES (${purchase.id}, ${line.bookId}, ${line.quantity}, ${prices[line.bookId]})`);
  }
  for (const key of Object.keys(wanted)) {
    ctx.db.exec(ctx.sql`UPDATE book SET stock = stock - ${wanted[key]} WHERE id = ${Number(key)}`);
  }
  // Last, so that a declined or failed payment rolls everything back.
  const res = ctx.fetch("http://127.0.0.1:18090/payments", { method: "POST", body: { customerId: customer, amountCents: total } });
  if (!res.ok) {
    ctx.reject({ message: "payment service failed", code: "payment_failed", status: 502 });
  }
  let payment = null;
  try {
    payment = res.json();
  } catch (e) {
    payment = null;
  }
  const status = payment ? payment.status : null;
  if (status === "declined") {
    ctx.reject({ message: "payment declined", code: "payment_declined", status: 402 });
  }
  if (status !== "accepted") {
    ctx.reject({ message: "payment service failed", code: "payment_failed", status: 502 });
  }
  return purchase.id;
}
EOF
cat > refund.command.ts <<'EOF'
export function create(input, ctx) {
  const [purchase] = ctx.db.query(ctx.sql`SELECT id, refunded_at FROM purchase WHERE id = ${ctx.id} AND customer_id = ${ctx.get("customer")} FOR UPDATE`);
  if (!purchase) {
    ctx.reject({ message: `purchase ${ctx.id} not found`, code: "not_found", status: 404 });
  }
  if (purchase.refunded_at) {
    ctx.reject({ message: `purchase ${ctx.id} is already refunded`, code: "already_refunded", status: 409 });
  }
  const lines = ctx.db.query(ctx.sql`SELECT book_id, quantity FROM purchase_line WHERE purchase_id = ${ctx.id}`);
  for (const line of lines) {
    ctx.db.exec(ctx.sql`UPDATE book SET stock = stock + ${line.quantity} WHERE id = ${line.book_id}`);
  }
  ctx.db.exec(ctx.sql`UPDATE purchase SET refunded_at = now() WHERE id = ${ctx.id}`);
}
EOF
cat > sales_report.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  const from = ctx.get("from");
  const to = ctx.get("to");
  if (from !== null && to !== null && from > to) {
    ctx.reject({ message: "from must not be after to", hint: "Use from <= to, both YYYY-MM-DD.", code: "invalid_parameter", status: 400 });
  }
  return ctx.sql`SELECT b.title, sum(l.quantity)::int AS quantity, sum(l.quantity * l.unit_price_cents)::bigint AS "revenueCents"
    FROM purchase_line l
    JOIN purchase p ON p.id = l.purchase_id
    JOIN book b ON b.id = l.book_id
    WHERE p.refunded_at IS NULL
      AND (p.created_at AT TIME ZONE 'UTC') >= ${from}::date
      AND (p.created_at AT TIME ZONE 'UTC') < ${to}::date + 1
    GROUP BY b.id, b.title
    ORDER BY "revenueCents" DESC, b.title ASC, b.id ASC`;
}
EOF
cat > customer.handler.ts <<'EOF'
export default function customer(id: number, ctx) {
  const [row] = ctx.db.query(ctx.sql`SELECT id FROM customer WHERE id = ${id}::bigint`);
  if (!row) ctx.reject({ message: `unknown customer ${id}` });
  ctx.set("customer", row.id);
  return null;
}
EOF
