cd /tmp/probe2 && cat > res/db.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT 1 AS id, (SELECT string_agg(id || ':' || stock, ',' ORDER BY id) FROM book) || ' | purchases=' || (SELECT count(*) FROM purchase) || ' | new=' || coalesce((SELECT string_agg(id || '/c' || customer_id || '/' || total_cents || '/' || coalesce(refunded_at::text,'-'), ' ; ' ORDER BY id) FROM purchase WHERE id > 8), 'none') || ' | newlines=' || (SELECT count(*) FROM purchase_line WHERE id > 13) AS info`;
}
EOF
sleep 2; curl -s localhost:18999/db | grep -o '"info":"[^"]*"'

cd /tmp/probe2 && cat > res/Clean.json <<'EOF'
{
  "name": "Clean", "path": "/clean", "query": "db.query.ts", "command": "clean.command.ts",
  "properties": { "id": {"type": "integer", "identifier": true}, "info": {"type": "string"} }
}
EOF
cat > res/clean.command.ts <<'EOF'
export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM purchase_line WHERE id > 13`);
  ctx.db.exec(ctx.sql`DELETE FROM purchase WHERE id > 8`);
}
EOF
sleep 2; curl -s -X DELETE localhost:18999/clean/1 -w ' %{http_code}\n'; sleep 1; curl -s localhost:18999/db | grep -o '"info":"[^"]*"'; curl -s -X PATCH -H 'Content-Type: application/json' -d '{"stock":10}' localhost:8089/books/4; echo

